static lstr L903 = {0, 4271, "#ifndef NARRA_IO_COMMON\012#define NARRA_IO_COMMON\012#include <errno.h>\012\012// True when p[0..n) is valid UTF-8: no overlong forms, no surrogates and\012// nothing above U+10FFFF.\012static bool narra_io_utf8(const unsigned char* p, int64_t n) {\012  int64_t i = 0;\012  while (i < n) {\012    unsigned char c = p[i];\012    int64_t k;\012    uint32_t cp;\012    if (c < 0x80) { i++; continue; }\012    if (c >= 0xC2 && c <= 0xDF) { k = 1; cp = c & 0x1F; }\012    else if (c >= 0xE0 && c <= 0xEF) { k = 2; cp = c & 0x0F; }\012    else if (c >= 0xF0 && c <= 0xF4) { k = 3; cp = c & 0x07; }\012    else return false;\012    if (i + k >= n) return false;\012    for (int64_t j = 1; j <= k; j++) {\012      if ((p[i + j] & 0xC0) != 0x80) return false;\012      cp = (cp << 6) | (p[i + j] & 0x3F);\012    }\012    if (k == 2 && (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF))) return false;\012    if (k == 3 && (cp < 0x10000 || cp > 0x10FFFF)) return false;\012    i += k + 1;\012  }\012  return true;\012}\012\012// A string from bytes; each byte that is not valid UTF-8 becomes U+FFFD.\012static lstr* narra_io_lossy(const char* p, size_t n) {\012  if (narra_io_utf8((const unsigned char*)p, (int64_t)n)) {\012    lstr* s = lstr_new((int64_t)n);\012    memcpy(s->data, p, n);\012    return s;\012  }\012  lstr* s = lstr_new((int64_t)n * 3);\012  int64_t o = 0;\012  size_t i = 0;\012  while (i < n) {\012    size_t k = 1;\012    unsigned char c = (unsigned char)p[i];\012    if (c >= 0xC2 && c <= 0xDF) k = 2;\012    else if (c >= 0xE0 && c <= 0xEF) k = 3;\012    else if (c >= 0xF0 && c <= 0xF4) k = 4;\012    if (c < 0x80 || (k > 1 && i + k <= n && narra_io_utf8((const unsigned char*)p + i, (int64_t)k))) {\012      memcpy(s->data + o, p + i, k);\012      o += (int64_t)k;\012      i += k;\012    } else {\012      memcpy(s->data + o, \"\\xEF\\xBF\\xBD\", 3);\012      o += 3;\012      i++;\012    }\012  }\012  s->len = o;\012  s->data[o] = 0;\012  return s;\012}\012\012// \"<what>: <message>\"\012static lstr* narra_io_fail(const char* what, int64_t whatlen, const char* msg) {\012  size_t ml = strlen(msg);\012  lstr* s = lstr_new(whatlen + 2 + (int64_t)ml);\012  memcpy(s->data, what, (size_t)whatlen);\012  memcpy(s->data + whatlen, \": \", 2);\012  memcpy(s->data + whatlen + 2, msg, ml);\012  return s;\012}\012\012// C strings end at the first zero byte, so a string with one inside cannot\012// name a file, a command or a variable.\012static bool narra_io_no_nul(lstr* s, lstr** err) {\012  if (memchr(s->data, 0, (size_t)s->len)) {\012    *err = lstr_from_cstr(\"argument contains a NUL byte\");\012    return false;\012  }\012  return true;\012}\012#endif\012\012\012#ifdef __APPLE__\012#include <crt_externs.h>\012#endif\012\012// NULL when the variable is not set.\012static lstr* narra_env_get(lstr* name) {\012  if (memchr(name->data, 0, (size_t)name->len)) return NULL;\012  const char* v = getenv(name->data);\012  return v \077 narra_io_lossy(v, strlen(v)) : NULL;\012}\012\012#ifdef __APPLE__\012static int64_t narra_env_argc(void) { return *_NSGetArgc(); }\012static lstr* narra_env_arg(int64_t i) {\012  const char* a = (*_NSGetArgv())[i];\012  return narra_io_lossy(a, strlen(a));\012}\012#else\012// Elsewhere the arguments are read once from /proc/self/cmdline.\012static char* narra_env_buf;\012static size_t narra_env_len;\012static int64_t narra_env_n = -1;\012\012static void narra_env_read(void) {\012  narra_env_n = 0;\012  FILE* f = fopen(\"/proc/self/cmdline\", \"rb\");\012  if (!f) return;\012  size_t cap = 4096;\012  narra_env_buf = malloc(cap);\012  while (narra_env_buf) {\012    if (narra_env_len == cap) {\012      char* bigger = realloc(narra_env_buf, cap * 2);\012      if (!bigger) break;\012      narra_env_buf = bigger;\012      cap *= 2;\012    }\012    size_t got = fread(narra_env_buf + narra_env_len, 1, cap - narra_env_len, f);\012    if (got == 0) break;\012    narra_env_len += got;\012  }\012  fclose(f);\012  for (size_t i = 0; i < narra_env_len; i++) {\012    if (narra_env_buf[i] == 0) narra_env_n++;\012  }\012}\012\012// In thread mode (D111) two threads may ask at once, so the file is read once.\012#ifdef NARRA_THREADS\012static pthread_once_t narra_env_once = PTHREAD_ONCE_INIT;\012static void narra_env_load(void) { pthread_once(&narra_env_once, narra_env_read); }\012#else\012static void narra_env_load(void) {\012  if (narra_env_n < 0) narra_env_read();\012}\012#endif\012static int64_t narra_env_argc(void) { narra_env_load(); return narra_env_n; }\012static lstr* narra_env_arg(int64_t i) {\012  narra_env_load();\012  const char* p = narra_env_buf;\012  while (i-- > 0) p += strlen(p) + 1;\012  return narra_io_lossy(p, strlen(p));\012}\012#endif\012"};
