static lstr L10207 = {0, 2626, "// std/async/file: whole-file reads and writes for async code (SPEC.md section 8, D109).\012//\012// kqueue and epoll do not wait on regular files, so each call reads or writes\012// in one blocking step, as std/fs does, then lets the other ready tasks run\012// once before it returns. A cancelled task's call gives\012// Err(AsyncError.Cancelled) before it touches the file.\012\012import * as Fs from \"std/fs\"\012import * as Tasks from \"std/internal/async\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012// The text of the file at path.\012export async function readText(path: string): Result<string, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.readText(path)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(text) => Ok(text), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// The bytes of the file at path.\012export async function readBytes(path: string): Result<bytes, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.readBytes(path)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(data) => Ok(data), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// Writes text to the file at path, replacing it, and gives the bytes written.\012export async function writeText(\012  path: string,\012  text: string,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.writeText(path, text)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(count) => Ok(count), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// Writes data to the file at path, replacing it, and gives the bytes written.\012export async function writeBytes(\012  path: string,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.writeBytes(path, data)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(count) => Ok(count), Err(message) => Err(AsyncError.Failed(message)) }\012}\012"};
