static lstr L10235 = {0, 670, "// std/hash: hashing. `of` is the hash of a Hashable value and may change between builds.\012// `fnv1a` is FNV-1a 64 over the UTF-8 bytes of a string and never changes.\012\012import * as Str from \"std/string\"\012import * as U64 from \"std/u64\"\012import * as Ranges from \"std/range\"\012\012const FNV_OFFSET: u64 = 14695981039346656037\012const FNV_PRIME: u64 = 1099511628211\012\012export function of<T: Hashable>(value: T): int {\012  return Hashable.hash(value)\012}\012\012export function fnv1a(text: string): u64 {\012  let state = FNV_OFFSET\012  const length = Str.length(text)\012  for (const index of Ranges.upTo(length)) {\012    state = (state ^ U64.wrap(Str.byteAt(text, index))) * FNV_PRIME\012  }\012  return state\012}\012"};
