static lstr L10239 = {0, 6610, "// std/iterator: lazy and eager operators over generators (D118 item 1).\012//\012// A lazy operator is a generator function: it does no work until the result is\012// resumed, and it keeps its callback, so the callback is `escaping`. An eager\012// operator runs the source to its end or to the first answer, with a callback\012// that is not escaping. Every operator takes its source by value: a loop or a\012// resume inside it works on its own copy, and the caller's generator does not\012// move.\012\012import * as Co from \"std/coroutine\"\012import { Step } from \"std/coroutine\"\012import * as Arrays from \"std/array\"\012\012export function* map<T, U, effect E>(\012  source: Generator<T> uses E,\012  escaping transform: (value: T) => U uses E,\012): Generator<U> uses E {\012  for (const value of source) {\012    yield transform(value)\012  }\012}\012\012export function* filter<T, effect E>(\012  source: Generator<T> uses E,\012  escaping keep: (value: T) => bool uses E,\012): Generator<T> uses E {\012  for (const value of source) {\012    if (keep(value)) {\012      yield value\012    }\012  }\012}\012\012export function* flatMap<T, U, effect E>(\012  source: Generator<T> uses E,\012  escaping expand: (value: T) => Generator<U> uses E uses (E, alloc),\012): Generator<U> uses (E, alloc) {\012  for (const value of source) {\012    for (const inner of expand(value)) {\012      yield inner\012    }\012  }\012}\012\012export function* take<T, effect E>(source: Generator<T> uses E, count: int): Generator<T> uses E {\012  // A count of 0 or less yields nothing and never resumes the source.\012  if (count <= 0) {\012    return\012  }\012  let taken = 0\012  for (const value of source) {\012    yield value\012    taken = taken + 1\012    if (taken >= count) {\012      return\012    }\012  }\012}\012\012export function* drop<T, effect E>(source: Generator<T> uses E, count: int): Generator<T> uses E {\012  let skipped = 0\012  for (const value of source) {\012    if (skipped < count) {\012      skipped = skipped + 1\012    } else {\012      yield value\012    }\012  }\012}\012\012export function* takeWhile<T, effect E>(\012  source: Generator<T> uses E,\012  escaping keep: (value: T) => bool uses E,\012): Generator<T> uses E {\012  for (const value of source) {\012    if (!keep(value)) {\012      return\012    }\012    yield value\012  }\012}\012\012export function* dropWhile<T, effect E>(\012  source: Generator<T> uses E,\012  escaping skip: (value: T) => bool uses E,\012): Generator<T> uses E {\012  let dropping = true\012  for (const value of source) {\012    if (dropping && skip(value)) {\012      continue\012    }\012    dropping = false\012    yield value\012  }\012}\012\012export function* enumerate<T, effect E>(source: Generator<T> uses E): Generator<#[int, T]> uses E {\012  let index = 0\012  for (const value of source) {\012    yield #[index, value]\012    index = index + 1\012  }\012}\012\012export function* zip<A, B, effect E>(\012  first: Generator<A> uses E,\012  second: Generator<B> uses E,\012): Generator<#[A, B]> uses (E, alloc) {\012  // A generator parameter cannot be `mutable`, so the second source is resumed\012  // through a local copy of its own.\012  let other = copy(second)\012  for (const value of first) {\012    const step = Co.resume(mutable other)\012    if (step is Step.Yielded(otherValue)) {\012      yield #[value, otherValue]\012    } else {\012      return\012    }\012  }\012}\012\012export function* concat<T, effect E>(\012  first: Generator<T> uses E,\012  second: Generator<T> uses E,\012): Generator<T> uses E {\012  for (const value of first) {\012    yield value\012  }\012  for (const value of second) {\012    yield value\012  }\012}\012\012export function chunk<T, effect E>(\012  source: Generator<T> uses E,\012  size: int,\012): Option<Generator<Array<T>> uses (E, alloc)> uses alloc {\012  // A size below 1 has no chunks to yield.\012  if (size < 1) {\012    return None\012  }\012  return Some(chunkFrom(source, size))\012}\012\012function* chunkFrom<T, effect E>(\012  source: Generator<T> uses E,\012  size: int,\012): Generator<Array<T>> uses (E, alloc) {\012  // The last chunk may be shorter than size; an empty source yields none.\012  let current: Array<T> = []\012  for (const value of source) {\012    Arrays.push(mutable current, value)\012    if (Arrays.length(current) == size) {\012      yield current\012      current = []\012    }\012  }\012  if (Arrays.length(current) > 0) {\012    yield current\012  }\012}\012\012export function window<T, effect E>(\012  source: Generator<T> uses E,\012  size: int,\012): Option<Generator<Array<T>> uses (E, alloc)> uses alloc {\012  // A size below 1 has no windows to yield.\012  if (size < 1) {\012    return None\012  }\012  return Some(windowFrom(source, size))\012}\012\012function* windowFrom<T, effect E>(\012  source: Generator<T> uses E,\012  size: int,\012): Generator<Array<T>> uses (E, alloc) {\012  // Each window is the last size values; a source shorter than size yields none.\012  let recent: Array<T> = []\012  for (const value of source) {\012    Arrays.push(mutable recent, value)\012    if (Arrays.length(recent) > size) {\012      recent = withoutFirst(recent)\012    }\012    if (Arrays.length(recent) == size) {\012      yield recent\012    }\012  }\012}\012\012function withoutFirst<T>(values: Array<T>): Array<T> from values uses alloc {\012  let rest: Array<T> = Arrays.withCapacity(Arrays.length(values))\012  let index = 1\012  while (index < Arrays.length(values)) {\012    Arrays.push(mutable rest, values[index])\012    index = index + 1\012  }\012  return rest\012}\012\012export function reduce<T, U, effect E>(\012  source: Generator<T> uses E,\012  combine: (total: U, value: T) => U uses E,\012  initial: U,\012): U from initial uses E {\012  let total = initial\012  for (const value of source) {\012    total = combine(total, value)\012  }\012  return total\012}\012\012export function toArray<T, effect E>(\012  source: Generator<T> uses E,\012): Array<T> from source uses E, alloc {\012  let values: Array<T> = []\012  for (const value of source) {\012    Arrays.push(mutable values, value)\012  }\012  return values\012}\012\012export function forEach<T, effect E>(\012  source: Generator<T> uses E,\012  visit: (value: T) => void uses E,\012) uses E {\012  for (const value of source) {\012    visit(value)\012  }\012}\012\012export function some<T, effect E>(\012  source: Generator<T> uses E,\012  predicate: (value: T) => bool uses E,\012): bool uses E {\012  for (const value of source) {\012    if (predicate(value)) {\012      return true\012    }\012  }\012  return false\012}\012\012export function every<T, effect E>(\012  source: Generator<T> uses E,\012  predicate: (value: T) => bool uses E,\012): bool uses E {\012  for (const value of source) {\012    if (!predicate(value)) {\012      return false\012    }\012  }\012  return true\012}\012\012export function find<T, effect E>(\012  source: Generator<T> uses E,\012  predicate: (value: T) => bool uses E,\012): Option<T> from source uses E {\012  for (const value of source) {\012    if (predicate(value)) {\012      return Some(value)\012    }\012  }\012  return None\012}\012\012export function count<T, effect E>(source: Generator<T> uses E): int uses E {\012  let total = 0\012  for (const _value of source) {\012    total = total + 1\012  }\012  return total\012}\012"};
